def historical_check_snapshots(
    session: Session,
    results: Sequence[Result],
    checks: Mapping[uuid.UUID, Check],
) -> dict[uuid.UUID, CheckAsOf]:
    """Per-**result** `CheckAsOf`, each as of WHEN that result was written."""
    return historical_check_snapshots_at(
        session, {r.id: (r.check_id, r.created_at) for r in results}, checks
    )


def historical_check_context_at[K: Hashable](
    session: Session,
    subjects: Mapping[K, tuple[uuid.UUID | None, datetime]],
    checks: Mapping[uuid.UUID, Check],
) -> dict[K, tuple[str | None, str | None]]:
    """`(tested_column, expectation_type)` per subject key — a projection of
    `historical_check_snapshots_at`.
    """
    snapshots = historical_check_snapshots_at(session, subjects, checks)
    return {key: snap.context for key, snap in snapshots.items()}


def historical_check_context(
    session: Session,
    results: Sequence[Result],
    checks: Mapping[uuid.UUID, Check],
) -> dict[uuid.UUID, tuple[str | None, str | None]]:
    """Per-**result** `(tested_column, expectation_type)`, resolved as of WHEN that
    result was written — not the check's CURRENT state (#1489).
    """
    snapshots = historical_check_snapshots(session, results, checks)
    return {r_id: snap.context for r_id, snap in snapshots.items()}


def historical_check_engine(
    session: Session,
    results: Sequence[Result],
    checks: Mapping[uuid.UUID, Check],
) -> dict[uuid.UUID, str]:
    """Per-**result** `engine` (ADR 0036) as of WHEN that result was written — a check
    re-pointed gx<->dmf after a run must not have its old results' `engine` reported
    as the check's current one (#1869 review).
    """
    snapshots = historical_check_snapshots(session, results, checks)
    return {r_id: snap.engine for r_id, snap in snapshots.items()}


def historical_check_kind(
    session: Session,
    results: Sequence[Result],
    checks: Mapping[uuid.UUID, Check],
) -> dict[uuid.UUID, str | None]:
    """Per-**result** `kind` as of WHEN that result was written. `CheckVersion.kind`
    is immutable in today's editor but snapshotted anyway (see the model) so a stale
    result is never re-labeled by a later edit (#1880 review).
    """
    snapshots = historical_check_snapshots(session, results, checks)
    return {r_id: snap.kind for r_id, snap in snapshots.items()}


# Expectation types whose scalar `observed_value` is a literal cell, not a computed statistic
# (#1486).
_CELL_SCALAR_EXPECTATION_TYPES = frozenset(
    {
        "expect_column_max_to_be_between",
        "expect_column_min_to_be_between",
    }
)
_AGGREGATE_EXPECTATION_TYPE = monitor_expectation_type(AGGREGATE)


def is_cell_scalar(expectation_type: str | None, observed: Mapping[str, Any] | None) -> bool:
    """Whether a scalar `observed_value` is one literal cell: GX's min/max expectations, and an
    `aggregate` monitor measuring MIN or MAX (its `observed_value` names which).
    """
    if expectation_type in _CELL_SCALAR_EXPECTATION_TYPES:
        return True
    return (
        expectation_type == _AGGREGATE_EXPECTATION_TYPE
        and observed is not None
        and observed.get("aggregate") in AGGREGATE_CELL_VALUES
    )


def _strip_row_level_observed_value(
    observed: dict[str, Any] | None, *, expectation_type: str | None
) -> dict[str, Any] | None:
    """Zero-sample mode (#1676): drop `observed_value`'s inner value when it is itself
    row-level data — a list of real column values (set/distinct-value expectations), or a
    literal cell (`_CELL_SCALAR_EXPECTATION_TYPES`) — rather than a computed aggregate.

    Mirrors the read-time ladder's own classification (`redact_observed_value`) but applies
    UNCONDITIONALLY, not gated by column policy/tags: zero-sample mode's whole point is not
    persisting the value at all, not persisting it and masking it on read.
    """
    if not isinstance(observed, dict) or "observed_value" not in observed:
        return observed
    value = observed["observed_value"]
    row_level = isinstance(value, list) or is_cell_scalar(expectation_type, observed)
    if not row_level:
        return observed
    return {key: val for key, val in observed.items() if key != "observed_value"}


def observed_value_exposes_cells(
    redacted: dict[str, Any] | None,
    *,
    expectation_type: str | None = None,
) -> bool:
    """Whether a **redacted** `observed_value` still carries raw cell values."""
    if not isinstance(redacted, dict):
        return False
    values = redacted.get("observed_value")
    if isinstance(values, list) and any(v != _REDACTED_VALUE for v in values):
        return True
    if (
        is_cell_scalar(expectation_type, redacted)
        and values is not None
        and values != _REDACTED_VALUE
    ):
        return True
    unparsed = redacted.get("unparsed_value")
    return unparsed is not None and unparsed != _REDACTED_VALUE


def _columnless_scalar_shows(
    value: Any,
    policy: Mapping[str, Any] | None,
    tags: Mapping[str, str] | None,
    *,
    expectation_type: str | None,
) -> bool:
    """Whether a scalar `observed_value` with NO tested column may show (#1793).

    With no column nothing a tag or policy can clear it: it shows only when the producing
    type makes it a statistic (row / unexpected-row count), not a cell
    (`_CELL_SCALAR_EXPECTATION_TYPES`); an unknown type fails closed like the list branch.
    The ladder still runs under an empty name so the value-shape signal and fail-closed
    mode (G3) apply rather than being short-circuited.
    """
    if expectation_type is None or expectation_type in _CELL_SCALAR_EXPECTATION_TYPES:
        return False
    return not _known_sensitive("", [value], policy, tags)


def redact_observed_value(
    observed: dict[str, Any] | None,
    *,
    tested_column: str | None = None,
    policy: dict[str, Any] | None = None,
    tags: Mapping[str, str] | None = None,
    expectation_type: str | None = None,
) -> dict[str, Any] | None:
    """Redact a result's `observed_value` for the read API (#989, #1229).

    `expectation_type` is what lets a column-less scalar be shown at all (#1793) —
    pass it whenever the caller knows it.
    """
    if not observed:
        return observed
    error = observed.get("error")
    if isinstance(error, str):
        observed = {**observed, "error": strip_statement_echo(error)}
    if "unparsed_value" in observed:
        column = str(observed.get("column") or "")
        value = observed.get("unparsed_value")
        show = bool(column) and not _known_sensitive(column, [value], policy, tags)
        return {**observed, "unparsed_value": value if show else _redact_sample_value(value)}
    if "observed_value" not in observed:
        return observed
    raw_observed_value = observed["observed_value"]
    if isinstance(raw_observed_value, list):
        show = tested_column is not None and not _known_sensitive(
            tested_column, raw_observed_value, policy, tags
        )
        capped = raw_observed_value[:SAMPLE_ROW_CAP]
        return {**observed, "observed_value": capped if show else _redact_sample_value(capped)}
    if tested_column is not None:
        show = not _known_sensitive(tested_column, [raw_observed_value], policy, tags)
    else:
        show = _columnless_scalar_shows(
            raw_observed_value, policy, tags, expectation_type=expectation_type
        )
    if show:
        return observed
    return {**observed, "observed_value": _redact_sample_value(raw_observed_value)}


def redact_sample_failures(
    sample: dict[str, Any] | None,
    *,
    tested_column: str | None = None,
    policy: dict[str, Any] | None = None,
    tags: Mapping[str, str] | None = None,
    tracker: _RedactionTracker | None = None,
) -> dict[str, Any] | None:
    """Redact a result's `sample_failures` for safe surfacing on the read API."""
    if not sample:
        return None
    index_rows = sample.get("unexpected_index_list")
    index_vbc = _values_by_column(index_rows) if isinstance(index_rows, list) else {}

    if lowers and uppers and max(lowers) > min(uppers):
        raise MonitorConfigError(
            f"aggregate lower bound {max(lowers)} is above upper bound {min(uppers)} — no value "
            "could pass"
        )
    return AggregateParams(aggregate=str(aggregate), column=column, bounds=bounds)


def aggregate_value(scalar: Any, *, source: str) -> float | None:
    """A SQL aggregate scalar → float, ``None`` kept as ``None`` (no non-NULL input). Drivers hand
    back ``Decimal`` (Snowflake, Databricks, psycopg2 NUMERIC), ``int`` or ``float``.
    """
    if scalar is None:
        return None
    if isinstance(scalar, bool) or not isinstance(scalar, (int, float, Decimal)):
        # The value is target data — never echoed, only its type.
        raise MonitorConfigError(
            f"{source} is not numeric (got {type(scalar).__name__}) — an aggregate monitor "
            "needs a numeric column"
        )
    value = float(scalar)
    if not math.isfinite(value):
        raise MonitorConfigError(f"{source} is not a finite number (NaN or infinity)")
    return value


def aggregate_of_series(series: Any, aggregate: str, *, source: str) -> float | None:
    """The aggregate of a pandas Series (flat files, Iceberg) with SQL's NULL semantics: NULLs are
    skipped, and no non-NULL input — or fewer than two for ``stdev`` — gives ``None``, never the
    ``0`` pandas returns for an empty sum.
    """
    import numpy as np
    import pandas as pd

    if pd.api.types.is_bool_dtype(series.dtype):
        raise MonitorConfigError(f"{source} is over a boolean column, not a numeric one")
    values = series.dropna()
    if pd.api.types.is_numeric_dtype(values.dtype):
        array = values.astype("float64").to_numpy()
    elif values.dtype == object and all(
        isinstance(v, (int, float, Decimal)) and not isinstance(v, bool) for v in values
    ):
        array = np.array([float(v) for v in values], dtype="float64")
    else:
        raise MonitorConfigError(
            f"{source} is over a non-numeric column (dtype {values.dtype}) — an aggregate "
            "monitor needs a numeric column"
        )
    array = array[~np.isnan(array)]
